// Device primitives: vector types, 16 B loads and stores, the fp8 MFMA, wave and block
// reductions.
#pragma once

#include <hip/hip_runtime.h>

#include "common/hw.h"

namespace infera_flash {

using bfloat16 = __bf16; // not hip_bfloat16: it rounds in software, with a branch per value

using uint32x4 = uint32_t __attribute__((ext_vector_type(4)));
using int32x4  = int __attribute__((ext_vector_type(4)));
using int32x8  = int __attribute__((ext_vector_type(8)));
using floatx2  = float __attribute__((ext_vector_type(2)));
using floatx4  = float __attribute__((ext_vector_type(4)));

template <typename T, int N> __device__ inline void load_data(const T *src, T *dst) {
    static_assert(N * sizeof(T) == 16, "Only 16 bytes are supported.");
    *reinterpret_cast<uint4 *>(dst) = *reinterpret_cast<const uint4 *>(src);
}

template <typename T, int N> __device__ inline void store_data(T *dst, const T *src) {
    static_assert(N * sizeof(T) == 16, "Only 16 bytes are supported.");
    *reinterpret_cast<uint4 *>(dst) = *reinterpret_cast<const uint4 *>(src);
}

// __syncthreads also waits for every global load in flight; this waits for LDS accesses only.
__device__ inline void block_sync_lds() {
    asm volatile("s_waitcnt lgkmcnt(0)" ::: "memory");
    __builtin_amdgcn_s_barrier();
}

// One lane's 32 B of an fp8 MFMA 16x16x128 operand: K bytes 16g..16g+15 and 64+16g..64+16g+15 of
// row (A) or column (B) l % 16, for g = l / 16 (ISA layout).
__device__ inline int32x8 load_fragment(const uint8_t *first, const uint8_t *second) {
    const int32x4 lo = *reinterpret_cast<const int32x4 *>(first);
    const int32x4 hi = *reinterpret_cast<const int32x4 *>(second);
    return __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
}

// load_fragment with nt, for weights read once a call: they stream through L2 and the MALL instead
// of pushing out what is read again
__device__ inline int32x8 load_fragment_nt(const uint8_t *first, const uint8_t *second) {
    const int32x4 lo = __builtin_nontemporal_load(reinterpret_cast<const int32x4 *>(first));
    const int32x4 hi = __builtin_nontemporal_load(reinterpret_cast<const int32x4 *>(second));
    return __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
}

// D = A B for 16x16 fp8 e4m3 tiles over K = 128; lane l gets D[4 (l / 16) + i][l % 16] in element
// i. Zero scales make the compiler emit the instruction without block scaling.
__device__ inline floatx4 mfma_16x16x128_fp8(int32x8 a, int32x8 b) {
    return __builtin_amdgcn_mfma_scale_f32_16x16x128_f8f6f4(a, b, floatx4{}, 0, 0, 0, 0, 0, 0);
}

template <typename T> struct SumOp {
    __device__ static T op(const T &x, const T &y) { return x + y; }
};

template <typename T> struct MaxOp {
    __device__ static T op(const T &x, const T &y) { return x > y ? x : y; }
};

// Orders like the float, as an unsigned integer.
__device__ __forceinline__ uint32_t ordered_bits(float x) {
    const uint32_t bits = __float_as_uint(x);
    return (bits & 0x80000000u) ? ~bits : bits | 0x80000000u;
}

// Each lane gets the value of the lane that DPP_CTRL picks within its 16-lane row. bound_ctrl lets
// the compiler fold the move into the instruction that uses it.
template <int DPP_CTRL, typename T> __device__ inline T dpp_mov(T val) {
    static_assert(sizeof(T) == 4);
    return __builtin_bit_cast(
        T, __builtin_amdgcn_mov_dpp(__builtin_bit_cast(int, val), DPP_CTRL, 0xF, 0xF, true));
}

template <typename T> __device__ inline T readlane(T val, int lane) {
    static_assert(sizeof(T) == 4);
    return __builtin_bit_cast(T, __builtin_amdgcn_readlane(__builtin_bit_cast(int, val), lane));
}

// Reduces over each aligned group of WIDTH lanes; every lane gets its group's result. DPP within
// a 16-lane row; across rows, row 3 adds row 2 and then rows 0 + 1, and lane 63 is read out. No
// LDS round trip.
template <template <class> class Func, typename T, int WIDTH = THREADS_PER_WARP>
__device__ inline T WarpReduce(T val) {
    static_assert(WIDTH == 4 || WIDTH == 16 || WIDTH == THREADS_PER_WARP);
    val = Func<T>::op(dpp_mov<0xB1>(val), val); // quad_perm [1,0,3,2]
    val = Func<T>::op(dpp_mov<0x4E>(val), val); // quad_perm [2,3,0,1]
    if constexpr (WIDTH == 4) {
        return val;
    }
    val = Func<T>::op(dpp_mov<0x141>(val), val); // row_half_mirror
    val = Func<T>::op(dpp_mov<0x140>(val), val); // row_mirror
    if constexpr (WIDTH == THREADS_PER_WARP) {
        val = Func<T>::op(val, dpp_mov<0x142>(val)); // row_bcast:15, row r gets row r - 1
        val = Func<T>::op(val, dpp_mov<0x143>(val)); // row_bcast:31, rows 2, 3 get row 1
        val = readlane(val, 63);
    }
    return val;
}

// Every thread gets the result. Warps are combined in a fixed order so all blocks get the same
// bits. smem holds NUM_WARPS * N elements and can be reused as soon as this returns. LDS_ONLY
// syncs on LDS alone, leaving global loads in flight.
template <template <class> class Func, int BLOCK_SIZE, bool LDS_ONLY = false, typename T, int N>
__device__ inline void BlockReduce(T (&vals)[N], T *smem) {
    const auto sync = [] {
        if constexpr (LDS_ONLY) {
            block_sync_lds();
        } else {
            __syncthreads();
        }
    };
    constexpr int NUM_WARPS = BLOCK_SIZE / THREADS_PER_WARP;
    const int     warp_id   = threadIdx.x / THREADS_PER_WARP;
    const int     lane_id   = threadIdx.x % THREADS_PER_WARP;

#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = WarpReduce<Func>(vals[n]);
    }
    // not inside the loop above: a branch there would serialize the N independent reductions
    if (lane_id == 0) {
#pragma unroll
        for (int n = 0; n < N; ++n) {
            smem[warp_id * N + n] = vals[n];
        }
    }
    sync();
#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = smem[n];
#pragma unroll
        for (int w = 1; w < NUM_WARPS; ++w) {
            vals[n] = Func<T>::op(vals[n], smem[w * N + n]);
        }
    }
    sync();
}

} // namespace infera_flash

// MI355X as these kernels use it: block b runs on XCD b % NUM_XCDS.
#pragma once

namespace infera_flash {

constexpr int THREADS_PER_WARP = 64;

struct Hw {
    static constexpr int NUM_BLOCKS = 256; // one per CU
    static constexpr int NUM_XCDS   = 8;
    static constexpr int BLOCK_SIZE = 256;
    // all of a CU's LDS
    static constexpr int SMEM_SIZE = 160 * 1024;
};

constexpr int WAVES = Hw::BLOCK_SIZE / THREADS_PER_WARP; // a block's

} // namespace infera_flash

// Math the kernels share, rounded as HF rounds: bf16 pairs, fp8 quant, silu(gate) * up.
#pragma once

#include "common/device.h"
#include "common/hw.h"

namespace infera_flash {

using bfloat16x2 = bfloat16 __attribute__((ext_vector_type(2)));

// bf16 pairs to floats, exactly, for packed floatx2 math
__device__ inline floatx2 to_float2(bfloat16x2 v) { return __builtin_convertvector(v, floatx2); }

constexpr float FP8_MAX = 448.0f; // largest finite e4m3fn

// HF finegrained-fp8 quant of a 1x128 group held by 16 consecutive lanes, 8 values each: stores
// this lane's 8 fp8 values to q and returns the group's scale. A multiply and v_rcp where HF
// divides move a few values by one fp8 step.
__device__ inline float quant_fp8(const bfloat16 (&x)[8], uint8_t *q) {
    const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x);
    floatx2     v[4];
    float       amax = 0.0f;
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        v[j] = to_float2(x2[j]);
        amax = fmaxf(amax, fmaxf(fabsf(v[j].x), fabsf(v[j].y)));
    }
    // amax >= 0 orders like its bits: an integer max, whose DPP moves fold into it
    amax = __uint_as_float(WarpReduce<MaxOp, uint32_t, 16>(__float_as_uint(amax)));
    // at least the smallest normal float, so a group of tiny values keeps them
    const float scale     = fmaxf(amax * (1.0f / FP8_MAX), __FLT_MIN__);
    const float inv_scale = __builtin_amdgcn_rcpf(scale);
    uint32_t    fp8[2];
#pragma unroll
    for (int j = 0; j < 2; ++j) {
        const floatx2 lo = v[2 * j] * inv_scale; // packed: two values per instruction
        const floatx2 hi = v[2 * j + 1] * inv_scale;
        // the second convert overwrites the half the first keeps: no need to zero it
        const int any    = __builtin_bit_cast(int, lo.x);
        fp8[j]           = __builtin_amdgcn_cvt_pk_fp8_f32(
            hi.x, hi.y, __builtin_amdgcn_cvt_pk_fp8_f32(lo.x, lo.y, any, false), true);
    }
    *reinterpret_cast<uint2 *>(q) = *reinterpret_cast<const uint2 *>(fp8);
    return scale;
}

// HF's act_fn(gate) * up of the linears' bf16 outputs: silu and the product each round to bf16
__device__ __forceinline__ bfloat16 silu_mul(bfloat16 gate, bfloat16 up) {
    const float g    = gate;
    const float silu = static_cast<bfloat16>(g / (1.0f + expf(-g)));
    return static_cast<bfloat16>(silu * static_cast<float>(up));
}

} // namespace infera_flash

// GLM-5.3's MoE on one rank of 8 (TP8): the sizes the kernels are written for, per card where noted.
#pragma once

#include "common/hw.h"

namespace infera_flash::glm5 {

struct Config : Hw {
    static constexpr int HIDDEN_SIZE       = 6144;
    static constexpr int QUANT_GROUP_SIZE  = 128; // one fp8 scale per 1x128 of activations
    static constexpr int NUM_GROUPS        = HIDDEN_SIZE / QUANT_GROUP_SIZE;
    static constexpr int NUM_EXPERTS       = 256;
    static constexpr int INTERMEDIATE_SIZE = 256; // per card: 2048 / TP8
    static constexpr int TOP_K             = 8;
    // rows a call takes: decode and MTP drafts and verify, up to 2 requests of 7 drafts
    static constexpr int MAX_NUM_TOKENS    = 16;
    // ExpertTable slots: the shared expert, then the most distinct experts M tokens can pick
    static constexpr int MAX_SLOTS         = MAX_NUM_TOKENS * TOP_K + 1;
    // the shared expert's id: its weights come after the routed ones
    static constexpr int SHARED_EXPERT     = NUM_EXPERTS;
    // down: block k writes output rows ROWS_PER_BLOCK k ..
    static constexpr int ROWS_PER_BLOCK    = HIDDEN_SIZE / NUM_BLOCKS;
};

// each thread's 16 B chunks of a HIDDEN_SIZE row, a block's threads covering it
constexpr int ROW_LOADS = Config::HIDDEN_SIZE / (Config::BLOCK_SIZE * 8);
static_assert(ROW_LOADS * Config::BLOCK_SIZE * 8 == Config::HIDDEN_SIZE);

} // namespace infera_flash::glm5

// GLM-5.3-FP8's MoE on one TP8 rank for M <= 16 tokens, in three launches of one block per CU in
// which no block waits for another: each launch reads only what the launches before it wrote.
//   router_kernel: block b's router logit of expert b for every token, and block m < M token m's
//     fp8 quant per 1x128.
//   gate_up_kernel: every block picks each token's top-8 from the logits and groups the picks into
//     the expert table, then computes its share of the table's gate_up rows into act; block 0
//     writes the table.
//   down_kernel: block k's output rows 24k .. 24k + 23, the down of every expert in the table times
//     its routing weight, summed in table order.
#pragma once

#include <type_traits>

#include "common/device.h"
#include "common/math.h"
#include "glm5/config.h"

namespace infera_flash::glm5 {

// aiter-preshuffled weights come in groups of 16 rows; a group's 128-K block is a contiguous 2 KB
constexpr int K_BLOCK_BYTES = 16 * 128;

// The experts to run: the shared one first, then the picked routed ones in id order, with each
// token's weight (1 for the shared expert, 0 where a token didn't pick a routed one). Weights come
// first so each row is 16 B aligned.
struct alignas(16) ExpertTable {
    float w[Config::MAX_SLOTS][Config::MAX_NUM_TOKENS];
    int   ids[Config::MAX_SLOTS]; // -1 past count in the copy written out
    int   count;
};

// Shapes use M = num_tokens.
struct MoeParams {
    const bfloat16 *x;             // [M, HIDDEN_SIZE] the MoE's input
    const bfloat16 *router_weight; // [NUM_EXPERTS, HIDDEN_SIZE]
    const float    *router_bias;   // [NUM_EXPERTS]
    float           routed_scaling_factor;
    // [NUM_EXPERTS + 1, 2 * INTERMEDIATE_SIZE, HIDDEN_SIZE], gate rows then up rows, preshuffled by
    // aiter shuffle_weight(w, (16, 16)), with fp32 scales [NUM_EXPERTS + 1, 4, NUM_GROUPS], one per
    // 128 x 128 block
    const uint8_t *gate_up_weight;
    const float   *gate_up_scale;
    // [NUM_EXPERTS + 1, HIDDEN_SIZE, INTERMEDIATE_SIZE], preshuffled the same, with scales
    // [NUM_EXPERTS + 1, NUM_GROUPS, 2]
    const uint8_t *down_weight;
    const float   *down_scale;
    // this call's scratch, each written by one launch and read by the next
    float       *logits; // [MAX_NUM_TOKENS][NUM_EXPERTS], rounded to bf16
    uint8_t     *x_q;    // [MAX_NUM_TOKENS][HIDDEN_SIZE] fp8
    float       *x_s;    // [MAX_NUM_TOKENS][NUM_GROUPS]
    ExpertTable *table;
    // gate_up's h = silu(x gate^T) * (x up^T), rounded as HF does: [MAX_SLOTS, MAX_NUM_TOKENS,
    // INTERMEDIATE_SIZE], table slot order
    bfloat16 *act;
    bfloat16 *out; // [M, HIDDEN_SIZE] this rank's share
};

__device__ inline float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

// router: block b's logit of expert b for every token, as HF's F.linear(x.float(), W.float()) in
// fp32, rounded to bf16 as sglang's MoEGate returns it; block m < M also quantizes token m to fp8,
// a scale per 128.
template <int NUM_TOKENS>
__global__ __launch_bounds__(Config::BLOCK_SIZE) void router_kernel(const MoeParams p) {
    __shared__ float reduce_smem[WAVES * NUM_TOKENS];
    const int bid = blockIdx.x;
    const int tid = threadIdx.x;
    static_assert(Config::NUM_BLOCKS == Config::NUM_EXPERTS);

    bfloat16 router_regs[ROW_LOADS][8];
    bfloat16 x_regs[NUM_TOKENS][ROW_LOADS][8];
#pragma unroll
    for (int i = 0; i < ROW_LOADS; ++i) {
        load_data<bfloat16, 8>(
            p.router_weight + bid * Config::HIDDEN_SIZE + (i * Config::BLOCK_SIZE + tid) * 8,
            router_regs[i]);
    }
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            load_data<bfloat16, 8>(p.x + m * Config::HIDDEN_SIZE + (i * Config::BLOCK_SIZE + tid) * 8,
                                   x_regs[m][i]);
        }
    }

    float logits[NUM_TOKENS];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        logits[m] = 0.0f;
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x_regs[m][i]);
            const auto *w2 = reinterpret_cast<const bfloat16x2 *>(router_regs[i]);
#pragma unroll
            for (int j = 0; j < 4; ++j) {
                logits[m] = __builtin_amdgcn_fdot2_f32_bf16(x2[j], w2[j], logits[m], false);
            }
        }
    }
    BlockReduce<SumOp, Config::BLOCK_SIZE>(logits, reduce_smem);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        if (tid == m) {
            p.logits[m * Config::NUM_EXPERTS + bid] =
                static_cast<float>(static_cast<bfloat16>(logits[m]));
        }
    }

    // x quant for the expert GEMMs: a 1x128 group is 16 consecutive lanes
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        if (bid == m) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                const int   col   = (i * Config::BLOCK_SIZE + tid) * 8;
                const float scale = quant_fp8(x_regs[m][i], p.x_q + m * Config::HIDDEN_SIZE + col);
                if (tid % 16 == 0) {
                    p.x_s[m * Config::NUM_GROUPS + col / Config::QUANT_GROUP_SIZE] = scale;
                }
            }
        }
    }
}

// gate_up: an item is 8 gate rows and the matching 8 up rows of one expert, one 16-row MFMA tile.
// Table slot r owns items 32r .. 32r + 31 and block b takes items b, b + 256, ...; the 4 waves
// split K, 12 blocks of 128 each.
constexpr int WAVE_K_BLOCKS    = Config::NUM_GROUPS / WAVES;
constexpr int ITEMS_PER_EXPERT = Config::INTERMEDIATE_SIZE / 8;
// a block's items at most, M tokens picking 8 experts each besides the shared one
template <int NUM_TOKENS>
constexpr int MAX_ITEMS =
    ((NUM_TOKENS * Config::TOP_K + 1) * ITEMS_PER_EXPERT + Config::NUM_BLOCKS - 1) / Config::NUM_BLOCKS;
// a 16-row group of preshuffled weights
constexpr int GROUP_BYTES = 16 * Config::HIDDEN_SIZE;
// LDS: each wave's 16x16 fp32 result per item [MAX_ITEMS][4][64 lanes][4], then the items' weight
// scales [MAX_ITEMS][gate, up][NUM_GROUPS] padded to whole rounds of threads, so every thread
// stores without a branch: the compiler moves the load that feeds such a store into the branch,
// after the weight loads, and then waits for all of them
constexpr int ITEM_SCALES = 2 * Config::NUM_GROUPS;
template <int NUM_TOKENS>
constexpr int SCALES_PER_THREAD =
    (MAX_ITEMS<NUM_TOKENS> * ITEM_SCALES + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE;
constexpr int SMEM_SCALES_OFFSET =
    MAX_ITEMS<Config::MAX_NUM_TOKENS> * Config::BLOCK_SIZE * sizeof(floatx4);
constexpr int SMEM_GATE_UP_SIZE = SMEM_SCALES_OFFSET + SCALES_PER_THREAD<Config::MAX_NUM_TOKENS> *
                                                          Config::BLOCK_SIZE * sizeof(float);
// the bf16 results staged in the scales' LDS before they go out
static_assert(MAX_ITEMS<Config::MAX_NUM_TOKENS> * 8 * Config::MAX_NUM_TOKENS * sizeof(bfloat16) <=
              SCALES_PER_THREAD<Config::MAX_NUM_TOKENS> * Config::BLOCK_SIZE * sizeof(float));

// Calls run(integral_constant<N>) for n in 1 .. N, so each item count gets straight-line code.
template <int N, typename Run> __device__ __forceinline__ void with_count(int n, Run &&run) {
    if constexpr (N > 0) {
        if (n == N) {
            run(std::integral_constant<int, N>{});
        } else {
            with_count<N - 1>(n, run);
        }
    }
}

// This block's gate_up items, x and its scales from the router launch, the table in LDS; smem
// takes the partial sums and the items' weight scales.
template <int NUM_TOKENS>
__device__ __forceinline__ void gate_up_block(const uint8_t *x_q, const float *x_s,
                                              const ExpertTable &table, const uint8_t *weight,
                                              const float *weight_scale, bfloat16 *h,
                                              uint8_t *smem) {
    constexpr int ITEMS       = MAX_ITEMS<NUM_TOKENS>;
    constexpr int SCALE_LOADS = SCALES_PER_THREAD<NUM_TOKENS>;
    floatx4      *partials    = reinterpret_cast<floatx4 *>(smem);
    float        *scales      = reinterpret_cast<float *>(smem + SMEM_SCALES_OFFSET);
    const int     tid         = threadIdx.x;
    const int lane      = tid % THREADS_PER_WARP;
    const int kb0       = tid / THREADS_PER_WARP * WAVE_K_BLOCKS;
    const int first     = blockIdx.x;
    const int count     = __builtin_amdgcn_readfirstlane(table.count);
    const int num_items = (count * ITEMS_PER_EXPERT - first + Config::NUM_BLOCKS - 1) /
                          Config::NUM_BLOCKS;
    if (num_items <= 0) {
        return;
    }
    // 256 is a multiple of 32: all of this block's items are the same chunk
    const int  chunk   = first % ITEMS_PER_EXPERT;
    const auto slot_of = [&](int n) {
        return min((first + n * Config::NUM_BLOCKS) / ITEMS_PER_EXPERT, NUM_TOKENS * Config::TOP_K);
    };

    // everything but the weights first: global loads complete in issue order, so waiting for one
    // issued after the weights would wait for all of them. Past count, ids are 0.
    int experts[ITEMS];
#pragma unroll
    for (int n = 0; n < ITEMS; ++n) {
        experts[n] = __builtin_amdgcn_readfirstlane(table.ids[slot_of(n)]);
    }
    float item_scales[SCALE_LOADS];
#pragma unroll
    for (int k = 0; k < SCALE_LOADS; ++k) {
        const int i     = tid + k * Config::BLOCK_SIZE;
        const int n     = min(i / ITEM_SCALES, ITEMS - 1);
        const int block = table.ids[slot_of(n)] * 4 + i / Config::NUM_GROUPS % 2 * 2 + chunk / 16;
        item_scales[k]  = weight_scale[block * Config::NUM_GROUPS + i % Config::NUM_GROUPS];
    }
    // x is every item's B operand, with its scales; columns past M repeat token M - 1 and are
    // dropped
    const int token = min(lane % 16, NUM_TOKENS - 1);
    int32x8   x[WAVE_K_BLOCKS];
    float     x_scale[WAVE_K_BLOCKS];
#pragma unroll
    for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
        const uint8_t *src = x_q + token * Config::HIDDEN_SIZE + (kb0 + j) * 128 + lane / 16 * 16;
        x[j]               = load_fragment(src, src + 64);
        x_scale[j]         = x_s[token * Config::NUM_GROUPS + kb0 + j];
    }

    // lanes l % 16 < 8 take gate rows, the others the matching up rows; their results land in C
    // rows 0-7 (lanes 0-31) and 8-15 (lanes 32-63), in different 128-row scale blocks
    const int  row      = 8 * (chunk % 2) + lane % 8; // of its 16-row group
    const auto group_of = [&](int n) {
        return experts[n] * 2 * Config::INTERMEDIATE_SIZE / 16 +
               (lane % 16 < 8 ? 0 : Config::INTERMEDIATE_SIZE / 16) + chunk / 2;
    };
    const auto weight_of = [&](int n) {
        return weight + static_cast<size_t>(group_of(n)) * GROUP_BYTES + kb0 * K_BLOCK_BYTES +
               lane / 16 * 256 + row * 16;
    };
    // w[j] holds this wave's K block j of item n; it loads the next item's as soon as its MFMA has
    // read it
    int32x8    w[WAVE_K_BLOCKS];
    const auto load_w = [&](int j, int n) {
        const uint8_t *item = weight_of(n);
        w[j] = load_fragment_nt(item + j * K_BLOCK_BYTES, item + j * K_BLOCK_BYTES + 1024);
    };
#pragma unroll
    for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
        load_w(j, 0);
    }
#pragma unroll
    for (int k = 0; k < SCALE_LOADS; ++k) {
        scales[tid + k * Config::BLOCK_SIZE] = item_scales[k];
    }
    block_sync_lds();

    const auto item = [&](int n, auto prefetch) {
        floatx4      acc     = {};
        const float *w_scale = scales + n * ITEM_SCALES + (lane < 32 ? 0 : Config::NUM_GROUPS) + kb0;
#pragma unroll
        for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
            acc += mfma_16x16x128_fp8(w[j], x[j]) * (w_scale[j] * x_scale[j]);
            if constexpr (prefetch) {
                load_w(j, n + 1);
            }
        }
        partials[n * Config::BLOCK_SIZE + tid] = acc;
    };
    // straight-line code per item count, so the compiler can count the loads in flight exactly
    with_count<ITEMS>(num_items, [&](auto items) {
#pragma unroll
        for (int n = 0; n < items - 1; ++n) {
            item(n, std::true_type{});
        }
        item(items - 1, std::false_type{});
    });
    __syncthreads();

    // (n, j, m): gate row j and up row j of token m in item n, summed over the 4 waves in a fixed
    // order; C row r of a wave's tile is at lane 16 (r / 4) + m, element r % 4
    for (int i = tid; i < num_items * 8 * NUM_TOKENS; i += Config::BLOCK_SIZE) {
        const int      n    = i / (8 * NUM_TOKENS);
        const int      j    = i / NUM_TOKENS % 8;
        const int      m    = i % NUM_TOKENS;
        const floatx4 *tile = partials + n * Config::BLOCK_SIZE + 16 * (j / 4) + m;
        float          gate = 0.0f;
        float          up   = 0.0f;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            gate += tile[v * THREADS_PER_WARP][j % 4];
            up += tile[v * THREADS_PER_WARP + 32][j % 4];
        }
        // HF: g and u are bf16 outputs of the linears
        reinterpret_cast<bfloat16 *>(scales)[i] =
            silu_mul(static_cast<bfloat16>(gate), static_cast<bfloat16>(up));
    }
    // (n, m): token m's 8 values of item n, from the scales' LDS, now free
    block_sync_lds();
    for (int i = tid; i < num_items * NUM_TOKENS; i += Config::BLOCK_SIZE) {
        const int   n   = i / NUM_TOKENS;
        const int   m   = i % NUM_TOKENS;
        const int   row = slot_of(n) * Config::MAX_NUM_TOKENS + m;
        const auto *v   = reinterpret_cast<const uint16_t *>(scales) + n * 8 * NUM_TOKENS + m;
        uint32x4    val;
#pragma unroll
        for (int j = 0; j < 4; ++j) {
            val[j] = v[2 * j * NUM_TOKENS] |
                     static_cast<uint32_t>(v[(2 * j + 1) * NUM_TOKENS]) << 16;
        }
        *reinterpret_cast<uint32x4 *>(h + row * Config::INTERMEDIATE_SIZE + 8 * chunk) = val;
    }
}

// gate_up_kernel's LDS: logits fp32 [MAX_NUM_TOKENS][NUM_EXPERTS], top-k expert ids int32 and
// weights fp32, each [MAX_NUM_TOKENS][TOP_K], a bit per expert picked by any token, the table,
// then gate_up_block's
constexpr int SMEM_LOGITS_OFFSET   = 0;
constexpr int SMEM_TOPK_IDS_OFFSET =
    SMEM_LOGITS_OFFSET + Config::MAX_NUM_TOKENS * Config::NUM_EXPERTS * sizeof(float);
constexpr int SMEM_TOPK_W_OFFSET =
    SMEM_TOPK_IDS_OFFSET + Config::MAX_NUM_TOKENS * Config::TOP_K * sizeof(int);
constexpr int SMEM_PICKED_MASK_OFFSET =
    SMEM_TOPK_W_OFFSET + Config::MAX_NUM_TOKENS * Config::TOP_K * sizeof(float);
constexpr int SMEM_TABLE_OFFSET   = SMEM_PICKED_MASK_OFFSET + Config::NUM_EXPERTS / 8;
constexpr int SMEM_GATE_UP_OFFSET = SMEM_TABLE_OFFSET + (sizeof(ExpertTable) + 15) / 16 * 16;
constexpr int GATE_UP_SMEM_SIZE   = SMEM_GATE_UP_OFFSET + SMEM_GATE_UP_SIZE;
static_assert(SMEM_TABLE_OFFSET % 16 == 0 && GATE_UP_SMEM_SIZE <= Config::SMEM_SIZE);

// top-k as in HF noaux_tc (n_group = topk_group = 1), on the logits rounded to bf16: wave w picks
// the experts of tokens w, w + 4, ... by sigmoid(logit) + bias, one wave-wide max per pick; ties go
// to the lower expert id. Then the grouping: the shared expert, then the picked ones in id order.
template <int NUM_TOKENS>
__global__ __launch_bounds__(Config::BLOCK_SIZE) __attribute__((amdgpu_waves_per_eu(1, 1))) void
gate_up_kernel(const MoeParams p) {
    extern __shared__ __align__(16) uint8_t smem[];
    const int tid     = threadIdx.x;
    const int warp_id = tid / THREADS_PER_WARP;
    const int lane_id = tid % THREADS_PER_WARP;
    // lane l scores experts l * EXPERTS_PER_LANE onward
    constexpr int EXPERTS_PER_LANE = Config::NUM_EXPERTS / THREADS_PER_WARP;
    static_assert(EXPERTS_PER_LANE == 4 && Config::BLOCK_SIZE == Config::NUM_EXPERTS);

    float    *logits      = reinterpret_cast<float *>(smem + SMEM_LOGITS_OFFSET);
    int      *topk_ids    = reinterpret_cast<int *>(smem + SMEM_TOPK_IDS_OFFSET);
    float    *topk_w      = reinterpret_cast<float *>(smem + SMEM_TOPK_W_OFFSET);
    uint32_t *picked_mask = reinterpret_cast<uint32_t *>(smem + SMEM_PICKED_MASK_OFFSET);
    ExpertTable &table    = *reinterpret_cast<ExpertTable *>(smem + SMEM_TABLE_OFFSET);

    float bias[EXPERTS_PER_LANE];
    load_data<float, 4>(p.router_bias + lane_id * EXPERTS_PER_LANE, bias);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        logits[m * Config::NUM_EXPERTS + tid] = p.logits[m * Config::NUM_EXPERTS + tid];
    }
    // zero the mask and the table: LDS starts with garbage, the top-k ORs its picks into the mask,
    // the grouping writes only the picked slots and the weights of tokens that picked them, and
    // gate_up reads scales for every slot it might take
    constexpr int ZERO_PACKETS = (SMEM_GATE_UP_OFFSET - SMEM_PICKED_MASK_OFFSET) / 16;
    for (int i = tid; i < ZERO_PACKETS; i += Config::BLOCK_SIZE) {
        reinterpret_cast<uint32x4 *>(smem + SMEM_PICKED_MASK_OFFSET)[i] = uint32x4{};
    }
    __syncthreads();

    for (int m = warp_id; m < NUM_TOKENS; m += WAVES) {
        const float *token_logits = logits + m * Config::NUM_EXPERTS;
        // this lane's experts, sorted by key and then e, so a pick only compares the lanes' heads
        // and only the picked lane moves on; ties go to the lowest lane, so the lowest expert id
        uint32_t key[EXPERTS_PER_LANE];
        int      eid[EXPERTS_PER_LANE];
#pragma unroll
        for (int e = 0; e < EXPERTS_PER_LANE; ++e) {
            key[e] = ordered_bits(sigmoid(token_logits[lane_id * EXPERTS_PER_LANE + e]) + bias[e]);
            eid[e] = e;
        }
        const auto order = [&](int a, int b) {
            const bool     swap = key[b] > key[a] || (key[b] == key[a] && eid[b] < eid[a]);
            const uint32_t ka   = key[a];
            const int      ea   = eid[a];
            key[a]              = swap ? key[b] : ka;
            eid[a]              = swap ? eid[b] : ea;
            key[b]              = swap ? ka : key[b];
            eid[b]              = swap ? ea : eid[b];
        };
        order(0, 1);
        order(2, 3);
        order(0, 2);
        order(1, 3);
        order(1, 2);
        int ids[Config::TOP_K];
#pragma unroll
        for (int k = 0; k < Config::TOP_K; ++k) {
            const uint32_t best   = WarpReduce<MaxOp, uint32_t>(key[0]);
            const int      lane   = __builtin_ctzll(__ballot(key[0] == best));
            ids[k]                = lane * EXPERTS_PER_LANE + readlane(eid[0], lane);
            const bool     picked = lane_id == lane;
#pragma unroll
            for (int e = 0; e + 1 < EXPERTS_PER_LANE; ++e) {
                key[e] = picked ? key[e + 1] : key[e];
                eid[e] = picked ? eid[e + 1] : eid[e];
            }
            key[EXPERTS_PER_LANE - 1] = picked ? 0 : key[EXPERTS_PER_LANE - 1];
        }
        // weights as in HF: sigmoid without the bias, normalized, then scaled; lane k keeps pick k,
        // so the stores and the mask OR below are one LDS instruction each for all 8 picks
        int   pick_id    = 0;
        float pick_score = 0.0f;
        float sum        = 0.0f;
#pragma unroll
        for (int k = 0; k < Config::TOP_K; ++k) {
            const float score = sigmoid(token_logits[ids[k]]);
            sum += score;
            pick_id    = lane_id == k ? ids[k] : pick_id;
            pick_score = lane_id == k ? score : pick_score;
        }
        const float norm = __builtin_amdgcn_rcpf(sum + 1e-20f) * p.routed_scaling_factor;
        if (lane_id < Config::TOP_K) {
            topk_ids[m * Config::TOP_K + lane_id] = pick_id;
            topk_w[m * Config::TOP_K + lane_id]   = pick_score * norm;
            atomicOr(picked_mask + pick_id / 32, 1u << pick_id % 32);
        }
    }
    __syncthreads();

    // thread t places pick t: its slot is 1 + how many picked ids are below it
    static_assert(Config::MAX_NUM_TOKENS * Config::TOP_K <= Config::BLOCK_SIZE);
    if (tid < NUM_TOKENS * Config::TOP_K) {
        const int pick_id = topk_ids[tid];
        uint32_t  mask[Config::NUM_EXPERTS / 32];
#pragma unroll
        for (int i = 0; i < Config::NUM_EXPERTS / 32; i += 4) {
            load_data<uint32_t, 4>(picked_mask + i, mask + i);
        }
        int rank  = 0;
        int count = 0;
#pragma unroll
        for (int i = 0; i < Config::NUM_EXPERTS / 32; ++i) {
            const int below = min(max(pick_id - 32 * i, 0), 32);
            rank += __popc(mask[i] & static_cast<uint32_t>((1ull << below) - 1));
            count += __popc(mask[i]);
        }
        table.ids[1 + rank]                    = pick_id;
        table.w[1 + rank][tid / Config::TOP_K] = topk_w[tid];
        if (tid == 0) {
            table.ids[0] = Config::SHARED_EXPERT;
#pragma unroll
            for (int m = 0; m < Config::MAX_NUM_TOKENS; ++m) {
                table.w[0][m] = 1.0f;
            }
            table.count = 1 + count;
        }
    }
    __syncthreads();

    // the table for the down launch: ids past count become -1
    if (blockIdx.x == 0) {
        if (tid < Config::MAX_SLOTS) {
            const int id = table.ids[tid];
#pragma unroll
            for (int j = 0; j < Config::MAX_NUM_TOKENS; j += 4) {
                store_data<float, 4>(p.table->w[tid] + j, table.w[tid] + j);
            }
            p.table->ids[tid] = tid < table.count ? id : -1;
        }
        if (tid == 0) {
            p.table->count = table.count;
        }
    }

    gate_up_block<NUM_TOKENS>(p.x_q, p.x_s, table, p.gate_up_weight, p.gate_up_scale, p.act,
                              smem + SMEM_GATE_UP_OFFSET);
}

// The row split of down: block k owns output rows 24k .. 24k + 23. Blocks 2j and 2j + 1 share
// 16-row groups 3j .. 3j + 2, the even one taking group 3j and rows 0-7 of 3j + 1, the odd one rows
// 8-15 of 3j + 1 and group 3j + 2. Waves 0 and 1 take the full group, waves 2 and 3 the half group,
// each pair splitting K; in the half group lanes 8-15 repeat the rows of lanes 0-7 and their C rows
// are dropped.
static_assert(Config::ROWS_PER_BLOCK == 24);
__device__ inline int split_group(int wave) {
    return blockIdx.x / 2 * 3 + (wave < 2 ? 2 * (blockIdx.x & 1) : 1);
}
// the row of its 16-row group this lane loads
__device__ inline int split_row(int wave, int lane) {
    return wave < 2 ? lane % 16 : lane % 8 + 8 * (blockIdx.x & 1);
}

// down: every expert of the table, wave w taking 128-K block w % 2 of its group; each wave keeps
// the next DOWN_DEPTH experts' weights in flight.
constexpr int DOWN_DEPTH       = 8;
constexpr int DOWN_GROUP_BYTES = 16 * Config::INTERMEDIATE_SIZE;
// a round's h: its 8 slots' 1x128 groups, (slot of the round, token, K block)
constexpr int H_GROUPS = DOWN_DEPTH * Config::MAX_NUM_TOKENS * 2;
// a round's h of one token is the block's 256 threads: its 8 slots' 2 groups of 16 lanes
static_assert(DOWN_DEPTH * 2 * 16 == Config::BLOCK_SIZE);

struct DownSmem {
    uint8_t     h[2][H_GROUPS * 128]; // fp8, by round parity
    float       coef[2][H_GROUPS];    // h's scale times the routing weight
    float       w_scale[Config::MAX_SLOTS][WAVES];
    floatx4     tiles[Config::BLOCK_SIZE]; // each wave's 16x16 result
    ExpertTable table;
};
static_assert(sizeof(DownSmem) <= Config::SMEM_SIZE);

template <int NUM_TOKENS>
__global__ __launch_bounds__(Config::BLOCK_SIZE) __attribute__((amdgpu_waves_per_eu(1, 1))) void
down_kernel(const MoeParams p) {
    extern __shared__ __align__(16) uint8_t smem[];
    DownSmem &s    = *reinterpret_cast<DownSmem *>(smem);
    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = tid / THREADS_PER_WARP;
    const int group = split_group(wave);
    const int row   = split_row(wave, lane);
    const int kb    = wave % 2;

    constexpr int TABLE_PACKETS = sizeof(ExpertTable) / sizeof(uint32x4);
    for (int i = tid; i < TABLE_PACKETS; i += Config::BLOCK_SIZE) {
        reinterpret_cast<uint32x4 *>(&s.table)[i] = reinterpret_cast<const uint32x4 *>(p.table)[i];
    }
    __syncthreads();
    const ExpertTable &table = s.table;
    const int          count = __builtin_amdgcn_readfirstlane(table.count);

    // the weight scales first, those of slot i / WAVES (past count, the last again) and wave
    // i % WAVES for thread i
    constexpr int SCALE_ITERS =
        (Config::MAX_SLOTS * WAVES + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE;
    float w_scale[SCALE_ITERS];
#pragma unroll
    for (int k = 0; k < SCALE_ITERS; ++k) {
        const int i    = tid + k * Config::BLOCK_SIZE;
        const int slot = min(i / WAVES, count - 1);
        const int wv   = i % WAVES;
        w_scale[k] = p.down_scale[(table.ids[slot] * Config::NUM_GROUPS + split_group(wv) / 8) * 2 +
                                  wv % 2];
    }
    // h of round r (slots 8r .. 8r + 7; past count, the last slot again) into LDS as fp8, a scale
    // per 1x128 group, while the round before computes: thread t takes slot 8r + t / 32, K block
    // t / 16 % 2 of each token
    const auto h_slot = [&](int round) { return min(round * DOWN_DEPTH + tid / 32, count - 1); };
    // the group's index in act, and in the round's LDS
    const auto act_group = [&](int round, int m) {
        return (h_slot(round) * Config::MAX_NUM_TOKENS + m) * 2 + tid / 16 % 2;
    };
    const auto lds_group = [&](int round, int m) {
        return ((h_slot(round) % DOWN_DEPTH) * Config::MAX_NUM_TOKENS + m) * 2 + tid / 16 % 2;
    };
    bfloat16   h[NUM_TOKENS][8];
    const auto load_h = [&](int round) {
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
            load_data<bfloat16, 8>(p.act + act_group(round, m) * 128 + tid % 16 * 8, h[m]);
        }
    };
    const auto quant_h = [&](int round) {
        float scale[NUM_TOKENS];
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
            scale[m] = quant_fp8(h[m], s.h[round % 2] + lds_group(round, m) * 128 + tid % 16 * 8);
        }
        // kept out of the loop above so that loop has no branches
        if (tid % 16 == 0) {
#pragma unroll
            for (int m = 0; m < NUM_TOKENS; ++m) {
                s.coef[round % 2][lds_group(round, m)] = scale[m] * table.w[h_slot(round)][m];
            }
        }
    };
    int32x8    w[DOWN_DEPTH];
    const auto load_w = [&](int d, int r) {
        const int      expert = __builtin_amdgcn_readfirstlane(table.ids[min(r, count - 1)]);
        const uint8_t *src =
            p.down_weight +
            (static_cast<size_t>(expert) * Config::HIDDEN_SIZE / 16 + group) * DOWN_GROUP_BYTES +
            kb * K_BLOCK_BYTES + lane / 16 * 256 + row * 16;
        w[d] = load_fragment_nt(src, src + 1024);
    };
    // round 0's h before its weights: global loads complete in issue order, so its quant waits
    // for h alone
    load_h(0);
#pragma unroll
    for (int d = 0; d < DOWN_DEPTH; ++d) {
        load_w(d, d);
    }
    quant_h(0);
#pragma unroll
    for (int k = 0; k < SCALE_ITERS; ++k) {
        const int i = tid + k * Config::BLOCK_SIZE;
        if (i < Config::MAX_SLOTS * WAVES) {
            s.w_scale[i / WAVES][i % WAVES] = w_scale[k];
        }
    }
    block_sync_lds();

    // columns past M repeat token M - 1 and are dropped
    const int  token  = min(lane % 16, NUM_TOKENS - 1);
    floatx4    acc    = {};
    const auto expert = [&](int r, int d) {
        if (r < count) {
            const int      g = (d * Config::MAX_NUM_TOKENS + token) * 2 + kb;
            const uint8_t *h = s.h[r / DOWN_DEPTH % 2] + g * 128 + lane / 16 * 16;
            acc += mfma_16x16x128_fp8(w[d], load_fragment(h, h + 64)) *
                   (s.w_scale[r][wave] * s.coef[r / DOWN_DEPTH % 2][g]);
        }
        // past count, the last expert's weights again: unused, but loading them keeps every
        // round's load count fixed for the compiler
        load_w(d, r + DOWN_DEPTH);
    };
    const int rounds = (count + DOWN_DEPTH - 1) / DOWN_DEPTH;
    for (int r = 0; r < rounds; ++r) {
        const bool has_next = r + 1 < rounds;
        if (has_next) {
            load_h(r + 1);
        }
#pragma unroll
        for (int d = 0; d < DOWN_DEPTH; ++d) {
            expert(r * DOWN_DEPTH + d, d);
        }
        if (has_next) {
            quant_h(r + 1);
            block_sync_lds();
        }
    }

    // block k's rows from its 4 waves' 16x16 tiles, split as above: even CUs the full group's 16
    // rows, then the half group's 8; odd CUs the other way round
    constexpr int ROWS = Config::ROWS_PER_BLOCK;
    s.tiles[tid]       = acc;
    block_sync_lds();
    for (int i = tid; i < ROWS * NUM_TOKENS; i += Config::BLOCK_SIZE) {
        const int      odd  = blockIdx.x & 1;
        const int      m    = i / ROWS;
        const int      q    = i % ROWS;
        const bool     full = odd ? q >= 8 : q < 16;
        const int      c    = full ? q - 8 * odd : q - 16 + 16 * odd;
        const floatx4 *tile = s.tiles + (full ? 0 : 2) * THREADS_PER_WARP + 16 * (c / 4) + m;
        p.out[m * Config::HIDDEN_SIZE + ROWS * blockIdx.x + q] =
            static_cast<bfloat16>(tile[0][c % 4] + tile[THREADS_PER_WARP][c % 4]);
    }
}

constexpr int DOWN_SMEM_SIZE = sizeof(DownSmem);

template <int NUM_TOKENS> void launch_moe(const MoeParams &p, hipStream_t stream) {
    router_kernel<NUM_TOKENS><<<Config::NUM_BLOCKS, Config::BLOCK_SIZE, 0, stream>>>(p);
    gate_up_kernel<NUM_TOKENS>
        <<<Config::NUM_BLOCKS, Config::BLOCK_SIZE, GATE_UP_SMEM_SIZE, stream>>>(p);
    down_kernel<NUM_TOKENS><<<Config::NUM_BLOCKS, Config::BLOCK_SIZE, DOWN_SMEM_SIZE, stream>>>(p);
}

// the launches for num_tokens in 1 .. MAX_NUM_TOKENS
template <int NUM_TOKENS = Config::MAX_NUM_TOKENS>
void moe_launch(const MoeParams &p, int num_tokens, hipStream_t stream) {
    if constexpr (NUM_TOKENS > 0) {
        if (num_tokens == NUM_TOKENS) {
            launch_moe<NUM_TOKENS>(p, stream);
        } else {
            moe_launch<NUM_TOKENS - 1>(p, num_tokens, stream);
        }
    }
}

} // namespace infera_flash::glm5

// GLM-5.3-FP8's DeepseekV2MoE on one TP8 rank for 1 to 16 tokens (decode, MTP drafts and verify):
// the router's logits in fp32 rounded to bf16, the sigmoid top-8 of the 256 routed experts with the
// fp32 correction bias added, their weights renormalized times routed_scaling_factor, and the
// shared expert in slot 256 at weight 1; each expert's gate_up and down GEMMs on sglang's
// preshuffled fp8 weights at a scale per 128 x 128 block, their inputs quantized to fp8 per 1 x 128,
// and the weighted sum written to out, this rank's share. Three launches of one block per CU, none
// waiting for another (glm5/moe.h): the router, the top-k with gate_up, then down.
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <ATen/hip/impl/HIPGuardImplMasqueradingAsCUDA.h>
#include <c10/hip/HIPException.h>
#include <optional>
#include <torch/library.h>

#include "glm5/moe.h"

namespace infera_flash::glm5 {
namespace {

// this call's scratch, at 256 B offsets into one allocation
constexpr int64_t align(int64_t bytes) { return (bytes + 255) / 256 * 256; }
constexpr int64_t LOGITS_BYTES =
    align(Config::MAX_NUM_TOKENS * Config::NUM_EXPERTS * sizeof(float));
constexpr int64_t X_Q_BYTES = align(Config::MAX_NUM_TOKENS * Config::HIDDEN_SIZE);
constexpr int64_t X_S_BYTES = align(Config::MAX_NUM_TOKENS * Config::NUM_GROUPS * sizeof(float));
constexpr int64_t TABLE_BYTES = align(sizeof(ExpertTable));
constexpr int64_t ACT_BYTES   = align(static_cast<int64_t>(Config::MAX_SLOTS) *
                                      Config::MAX_NUM_TOKENS * Config::INTERMEDIATE_SIZE *
                                      sizeof(bfloat16));

void run(const at::Tensor &hidden_states, const at::Tensor &router_weight,
         const at::Tensor &correction_bias, const at::Tensor &w1, const at::Tensor &w1_scale,
         const at::Tensor &w2, const at::Tensor &w2_scale, int64_t topk, int64_t num_expert_group,
         int64_t topk_group, bool renormalize, c10::string_view scoring_func,
         double routed_scaling_factor, std::optional<at::ScalarType> out_dtype, at::Tensor &out) {
    const int64_t num_tokens = hidden_states.size(0);
    TORCH_CHECK(num_tokens >= 1 && num_tokens <= Config::MAX_NUM_TOKENS &&
                    topk == Config::TOP_K && num_expert_group == 1 && topk_group == 1 &&
                    renormalize && scoring_func == "sigmoid",
                "1 to ", Config::MAX_NUM_TOKENS, " tokens and GLM-5's routing only");
    TORCH_CHECK(hidden_states.is_contiguous() && router_weight.is_contiguous() &&
                    correction_bias.is_contiguous() && w1.is_contiguous() &&
                    w1_scale.is_contiguous() && w2.is_contiguous() && w2_scale.is_contiguous() &&
                    out.is_contiguous(),
                "contiguous tensors only");
    const at::hip::OptionalHIPGuardMasqueradingAsCUDA guard(hidden_states.device());
    at::Tensor scratch = at::empty({LOGITS_BYTES + X_Q_BYTES + X_S_BYTES + TABLE_BYTES + ACT_BYTES},
                                   hidden_states.options().dtype(at::kByte));
    uint8_t   *base    = scratch.data_ptr<uint8_t>();

    MoeParams p{};
    p.x                     = static_cast<const bfloat16 *>(hidden_states.data_ptr());
    p.router_weight         = static_cast<const bfloat16 *>(router_weight.data_ptr());
    p.router_bias           = correction_bias.data_ptr<float>();
    p.routed_scaling_factor = static_cast<float>(routed_scaling_factor);
    p.gate_up_weight        = static_cast<const uint8_t *>(w1.data_ptr());
    p.gate_up_scale         = w1_scale.data_ptr<float>();
    p.down_weight           = static_cast<const uint8_t *>(w2.data_ptr());
    p.down_scale            = w2_scale.data_ptr<float>();
    p.logits                = reinterpret_cast<float *>(base);
    p.x_q                   = base + LOGITS_BYTES;
    p.x_s                   = reinterpret_cast<float *>(base + LOGITS_BYTES + X_Q_BYTES);
    p.table = reinterpret_cast<ExpertTable *>(base + LOGITS_BYTES + X_Q_BYTES + X_S_BYTES);
    p.act   = reinterpret_cast<bfloat16 *>(base + LOGITS_BYTES + X_Q_BYTES + X_S_BYTES +
                                         TABLE_BYTES);
    p.out   = static_cast<bfloat16 *>(out.data_ptr());
    moe_launch(p, static_cast<int>(num_tokens), at::hip::getCurrentHIPStream());
    C10_HIP_CHECK(hipGetLastError());
}

